style.css:
@-moz-document regexp(".*") {
/* 替换所有常规字体为 Fire Sans Heiti 或备用黑体 */
    * {
        font-family: "Fira Sans Heiti", sans-serif !important;
    }

    /* 替换所有等宽字体为 Ubuntu Mono B */
    pre, code, kbd, samp, tt,
    .monospace, .code, .editor,
    textarea, [class*="mono"], [class*="code"] {
        font-family: "Ubuntu Mono B", monospace !important;
        font-weight: bold !important; /* 确保加粗效果 */
    }

    /* 代码编辑器特殊处理（如 LeetCode、IDE 等） */
    .CodeMirror, .code-editor, .prism-editor {
        font-family: "Ubuntu Mono B", monospace !important;
        font-size: 14px !important; /* 优化代码可读性 */
    }
    /* === 动态内容兼容性优化 === */
    /* 修复图标类元素被覆盖的问题（如 Font Awesome） */
    [class*="icon"]:not(i),
    i {
        font-family: inherit !important; /* 继承父元素字体 */
    }

    /* === 增强可读性设置（可选） === */
    body {
        text-rendering: optimizeLegibility; /* 优化字体渲染 */
        -webkit-font-smoothing: antialiased; /* Mac 抗锯齿 */
    }
}
